const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const get=async(p)=>{try{return await this.helpers.httpRequest({method:'GET',url:SB+p,headers:H,json:true});}catch(e){return [];}};
// two most recent snapshot weeks
const weeks=await get('/sov_weekly?select=week_start&order=week_start.desc&limit=200');
const uniq=[...new Set(weeks.map(w=>w.week_start))].slice(0,2);
const [cur,prev]=uniq;
const curRows=cur?await get('/sov_weekly?select=company,weighted_pct,sentiment_pct,posts_count&week_start=eq.'+cur):[];
const prevRows=prev?await get('/sov_weekly?select=company,weighted_pct,sentiment_pct&week_start=eq.'+prev):[];
const prevMap=Object.fromEntries(prevRows.map(r=>[r.company,r]));
const comps=await get('/competitors?select=name,type&active=eq.true');
const direct=new Set(comps.filter(c=>(c.type||'direct')!=='indirect').map(c=>c.name));
const board=curRows.filter(r=>direct.has(r.company)).map(r=>({company:r.company,sov:Number(r.weighted_pct)||0,delta:prevMap[r.company]?(Number(r.weighted_pct)||0)-(Number(prevMap[r.company].weighted_pct)||0):null,sent:r.sentiment_pct!=null?((Number(r.sentiment_pct)/100)*6-3):null,posts:r.posts_count})).sort((a,b)=>b.sov-a.sov);
// top posts of interest this period (with strategic angles)
const poi=await get('/posts_of_interest?select=author,summary,strategic_angle,post_type,reactions,url,period_start&period_start=not.is.null&order=period_start.desc,reactions.desc.nullslast&limit=12');
const latestPeriod=poi.length?poi[0].period_start:null;
const topPoi=poi.filter(p=>p.period_start===latestPeriod).slice(0,5);
// AI-answer shares (tolerates table not existing yet)
const llm=await get('/llm_sov?select=engine,company,share_of_model,week_start&order=week_start.desc&limit=100');
const llmLatest=llm.length?llm.filter(r=>r.week_start===llm[0].week_start):[];
const payload={week:cur,prevWeek:prev,board,topPostsOfInterest:topPoi,aiVisibility:llmLatest};
const openaiBody={model:'gpt-4.1',temperature:0.4,messages:[
 {role:'system',content:'You are the competitive-intelligence analyst for Twine Security (identity security). Write the weekly Slack digest of the Share-of-Voice board. Format for Slack mrkdwn (*bold*, bullets with \u2022, <url|text> links). Structure: 1) one-line headline of the week; 2) *Board* — top movers with SOV and delta (arrow emoji), call out anything notable; 3) *Posts worth knowing* — the top posts of interest, one line each with the For-Twine angle; 4) *AI visibility* — one line per engine if data exists, else omit; 5) one *So what* action line. Under 300 words, no fluff, no headers other than the bold labels.'},
 {role:'user',content:JSON.stringify(payload)}]};
return [{json:{week:cur,openaiBody,boardSize:board.length,poiCount:topPoi.length}}];

const llm=$input.first().json;
let text='';
if(llm&&llm.choices&&llm.choices[0]&&llm.choices[0].message)text=llm.choices[0].message.content||'';
const week=$('Gather Week Data').first().json.week||'';
if(!text)text='(digest generation failed — check the SOV — Weekly Digest workflow)';
const head=`:bar_chart: *SOV Weekly Digest — week of ${week}*\n`;
const tail=`\n<https://competitive-intelligence-system.pages.dev|Open the board> \u00b7 generated automatically`;
return [{json:{slackText:head+text+tail}}];
